answer:
type Shape = { kind: 'circle'; r: number } | { kind: 'square'; a: number } | { kind: 'rect'; w: number; h: number };
function assertNever(x: never): never { throw new Error('Unexpected: ' + String(x)); }
function area(s: Shape): number {
  switch (s.kind) {
    case 'circle': return Math.PI * s.r * s.r;
    case 'square': return s.a * s.a;
    case 'rect': return s.w * s.h;
  }
  return assertNever(s as never);
}
